{
    [Fact]
    public async Task CommitAsync_ProbeFailsTwiceThenSucceeds_CommitsSuccessfully()
    {
        var (sim, repo) = NewRepo();
        using var _ = repo;
        sim.Seed(repo.Root, "src/app.cs", "content");
        sim.Commit(repo.Root, "chore: seed");
